ee:message.ee:set-payload:
%dw 2.0
output application/json
var lock = if (vars.currentAction == 'S') true else false
var lockValues = [{"name": "ISDN", "value": attributes.uriParams.misdn}, {"name": "ODBOC", "value": "BAOC"}, {"name": "ODBPOS", "value": "BAPOS"}, {"name": "ODBPOSTYPE", "value": "BOTH"}, {"name": "MSISDN", "value": attributes.uriParams.misdn}, {"name": "STATUS", "value": "3"}]
var unlockValues = [{"name": "ISDN", "value": attributes.uriParams.misdn}, {"name": "ODBOC", "value": "BOCROAM"}, {"name": "ODBPOS", "value": "NOBPOS"}, {"name": "ODBPOSTYPE", "value": "BOTH"}, {"name": "MSISDN", "value": attributes.uriParams.misdn}, {"name": "STATUS", "value": "2"}, {"name": "RECURSOS", "value": attributes.queryParams.recursos}]
---
createOrderByValueRequest: {
    orderValue: {
        apiClientId: if (lock)"LTESuspend-OracleComms_OSM_O2A_SomProvisionLTE_Sample-1.0.0.0.0" else "LTERec-OracleComms_OSM_O2A_SomProvisionLTE_Sample-1.0.0.0.0",
        orderKey: {
            applicationDN: "System/DEVC/ApplicationType/ServiceActivation/Application/1-0;7-2;ASAP/Comp/",
            'type': "javax.oss.order.CreateOrderValue",
            primaryKey: "MS-LTE" ++ correlationId
        },
        requestedCompletionDate: now() >> "America/Bogota",
        services: {
            item: {
                serviceKey: {
                    applicationContext: {
                        factoryClass: "",
                        url: "",
                        systemProperties: ""
                    },
                    applicationDN: "System/DEVC/ApplicationType/ServiceActivation/Application/1-0;7-2;ASAP/Comp/",
                    'type': if (lock) "C_SUS_LTE" else "C_REC_LTE",
                    primaryKey: if (lock) "C_SUS_LTE" else "C_REC_LTE"
                },
                asdlRoute: if (lock) "ROUTE_TO_NEP" else "",
                serviceValues: {
                    serviceValue : if (lock) lockValues map (item, value) -> {
                    name: item.name,
                    value: item.value,
                    'type': "OPTIONAL_SCALAR"
                } else unlockValues map ((item, index) -> {
                    name: item.name,
                    value: item.value,
                    'type': "OPTIONAL_SCALAR"
                })
                },

            }
        },
        origin: "OracleComms_OSM_O2A_SomProvisionLTE_SampleOrder",
        rollbackState: "rollback_required",
        processType: "IMMEDIATE",
        srqAction: "ADD",
        command: "UPDATE"
    }
}
